import React from 'react';
import { render, fireEvent, screen } from '@testing-library/react';

import { DatePicker } from './DatePicker';

jest.mock('@hexa-ui/theme', () => {
  const originalValue = jest.requireActual('@hexa-ui/theme');
  return {
    ...originalValue,
    useMatchMedia: jest.fn().mockReturnValue([false]),
  };
});

const newDateWithUTCHours = (date) => {
  const formattedDate = new Date(date);
  formattedDate.setUTCHours(12, 0, 0, 0);
  return formattedDate;
};

describe('DatePicker', () => {
  it('should reflect date value on input and calendar', () => {
    const date = newDateWithUTCHours('03/01/2023');
    render(<DatePicker value={[date]} />);

    expect(screen.getByTestId('date-picker-input')).toHaveValue('Mar 01, 2023');
    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByText('March 2023')).toBeInTheDocument();
    const dayButton = screen.getByRole('button', { name: '1st March (Wednesday)' });
    expect(dayButton).toHaveClass('hexa-ui-selected');
  });

  it('should call onChange with selected date on calendar and close it', () => {
    const onChangeMock = jest.fn();
    const initialDate = newDateWithUTCHours('03/01/2023');
    render(<DatePicker onChange={onChangeMock} value={[initialDate]} />);

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '2nd March (Thursday)' }));

    expect(onChangeMock).toHaveBeenCalledWith([newDateWithUTCHours('03/02/2023')]);
    expect(screen.queryByTestId('date-picker-calendar')).toBeNull();
  });

  it('should call onChange when typing a valid date on input', () => {
    const onChangeMock = jest.fn();
    const initialDate = newDateWithUTCHours('03/01/2023');
    render(<DatePicker onChange={onChangeMock} value={[initialDate]} />);

    fireEvent.change(screen.getByTestId('date-picker-input'), { target: { value: '03/02/2023' } });
    fireEvent.blur(screen.getByTestId('date-picker-input'));

    expect(onChangeMock).toHaveBeenCalledWith([newDateWithUTCHours('03/02/2023')]);
  });

  it('should not call onChange when selecting date on calendar with callToActionSection', () => {
    const onChangeMock = jest.fn();
    const initialDate = newDateWithUTCHours('03/01/2023');
    render(<DatePicker onChange={onChangeMock} value={[initialDate]} callToActionSection />);

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '2nd March (Thursday)' }));

    expect(onChangeMock).not.toHaveBeenCalled();
  });

  it('should call onSave when saving selected date on calendar with callToActionSection', () => {
    const onSaveMock = jest.fn();
    const onChangeMock = jest.fn();
    const initialDate = newDateWithUTCHours('03/01/2023');
    render(
      <DatePicker
        onChange={onChangeMock}
        onSave={onSaveMock}
        value={[initialDate]}
        callToActionSection
      />
    );

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '2nd March (Thursday)' }));
    expect(onChangeMock).not.toHaveBeenCalled();
    fireEvent.click(screen.getByTestId('date-picker-save-button'));
    expect(onSaveMock).toHaveBeenCalledWith([newDateWithUTCHours('03/02/2023')]);
    expect(screen.queryByTestId('date-picker-calendar')).toBeNull();
  });

  it('should reset date picker selection to the current value when clicking on reset', () => {
    const onSaveMock = jest.fn();
    const onChangeMock = jest.fn();
    const initialDate = newDateWithUTCHours('03/01/2023');
    render(
      <DatePicker
        onChange={onChangeMock}
        onSave={onSaveMock}
        value={[initialDate]}
        callToActionSection
      />
    );

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '2nd March (Thursday)' }));
    expect(onChangeMock).not.toHaveBeenCalled();
    fireEvent.click(screen.getByTestId('date-picker-reset-button'));
    expect(screen.getByRole('button', { name: '1st March (Wednesday)' })).toHaveClass(
      'hexa-ui-selected'
    );
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
  });

  it('should call onChange with selected range on calendar', () => {
    const onChangeMock = jest.fn();
    const initialRange = [newDateWithUTCHours('03/10/2023'), newDateWithUTCHours('03/20/2023')];
    render(<DatePicker onChange={onChangeMock} value={initialRange} mode="range" />);

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '1st March (Wednesday)' }));
    fireEvent.click(screen.getByRole('button', { name: '10th March (Friday)' }));

    expect(onChangeMock).toHaveBeenCalledWith([
      newDateWithUTCHours('03/01/2023'),
      newDateWithUTCHours('03/10/2023'),
    ]);
    expect(screen.queryByTestId('date-picker-calendar')).not.toBeNull();
  });

  it('should call onChange with selected range on calendar', () => {
    const onChangeMock = jest.fn();
    const onSaveMock = jest.fn();
    const initialRange = [newDateWithUTCHours('03/10/2023'), newDateWithUTCHours('03/20/2023')];
    render(
      <DatePicker
        onChange={onChangeMock}
        onSave={onSaveMock}
        value={initialRange}
        mode="range"
        callToActionSection
      />
    );

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByRole('button', { name: '1st March (Wednesday)' }));
    fireEvent.click(screen.getByRole('button', { name: '10th March (Friday)' }));

    expect(onChangeMock).not.toHaveBeenCalled();
    fireEvent.click(screen.getByTestId('date-picker-save-button'));
    expect(onSaveMock).toHaveBeenCalledWith([
      newDateWithUTCHours('03/01/2023'),
      newDateWithUTCHours('03/10/2023'),
    ]);
  });

  it('should close calendar when clicking on close button given numberOfMonths=2 and mode=single', () => {
    render(<DatePicker numberOfMonths={2} />);

    fireEvent.click(screen.getByTestId('Calendar'));
    expect(screen.getByTestId('date-picker-calendar')).toBeInTheDocument();
    fireEvent.click(screen.getByTestId('icon-button-close-x'));
    expect(screen.queryByTestId('date-picker-calendar')).toBeNull();
  });
});
